+/** Minimal single-value TTL cache used by the top-customers endpoint. */
+export class TtlCache<K, V> {
+  private store = new Map<K, { value: V; expiresAt: number }>();
+
+  constructor(private readonly ttlMs: number) {}
+
+  get(key: K): V | undefined {
+    const entry = this.store.get(key);
+    if (!entry) return undefined;
+    if (Date.now() > entry.expiresAt) {
+      this.store.delete(key);
+      return undefined;
+    }
+    return entry.value;
+  }
+
+  set(key: K, value: V): void {
+    this.store.set(key, { value, expiresAt: Date.now() + this.ttlMs });
+  }
+
+  /** Evict a single key — useful in tests or explicit invalidation. */
+  delete(key: K): void {
+    this.store.delete(key);
+  }
+
+  /** Remove all expired entries without clearing live ones. */
+  purgeExpired(): void {
+    const now = Date.now();
+    for (const [k, entry] of this.store) {
+      if (now > entry.expiresAt) this.store.delete(k);
+    }
+  }
+}
