diff --git a/demo/orders-api/src/db.ts b/demo/orders-api/src/db.ts
index fa3c0a9..f8b4de1 100644
--- a/demo/orders-api/src/db.ts
+++ b/demo/orders-api/src/db.ts
@@ -39,5 +39,38 @@ export async function openDb(): Promise<PGlite> {

     ANALYZE;
+
+    -- Materialized view: precomputed top-customer ranking for the last 30 days.
+    -- Reads are instant (index scan on revenue_cents); writes go to orders as
+    -- normal and the view is refreshed on a background schedule.
+    CREATE MATERIALIZED VIEW mv_top_customers AS
+    SELECT c.id          AS customer_id,
+           c.name,
+           sum(o.amount_cents)::int AS revenue_cents,
+           count(*)::int            AS orders
+    FROM orders o
+    JOIN customers c ON c.id = o.customer_id
+    WHERE o.status = 'paid'
+      AND o.created_at > now() - interval '30 days'
+    GROUP BY c.id, c.name
+    ORDER BY revenue_cents DESC;
+
+    -- Index so ORDER BY + LIMIT is a fast index scan, not a sort.
+    CREATE INDEX ON mv_top_customers (revenue_cents DESC);
   `);
   return db;
 }
+
+// Refresh the materialized view in the background on a fixed interval.
+// Returns a cancel function that stops the timer.
+export function startMatviewRefresher(db: PGlite, intervalMs: number = 10_000): () => void {
+  const timer = setInterval(async () => {
+    try {
+      await db.exec("REFRESH MATERIALIZED VIEW mv_top_customers;");
+    } catch {
+      // Swallow errors – a stale view is better than a crash.
+    }
+  }, intervalMs);
+  // Allow Node to exit without waiting for this timer.
+  timer.unref?.();
+  return () => clearInterval(timer);
+}
